using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows.Forms;
namespace F1Manager {
public static class UITests {
static readonly List<string> report=new List<string>();
static void Check(bool ok,string text){if(!ok)throw new Exception(text);report.Add("PASS "+text);}
static void Pump(Func<bool> ready,int timeout=8000){var clock=Stopwatch.StartNew();while(!ready()){Application.DoEvents();Thread.Sleep(8);if(clock.ElapsedMilliseconds>timeout)throw new Exception("UI timed out");}Application.DoEvents();}
static IEnumerable<Control> Children(Control host){foreach(Control child in host.Controls){yield return child;foreach(var nested in Children(child))yield return nested;}}
static void ChooseTyre(StrategyOverlay selector,int driver,int stint,string code){selector.StintChoices[driver][stint].PerformClick();selector.CompoundChoices[Array.IndexOf(TyrePhotos.Codes,code)].PerformClick();}
static void Settle(){var clock=Stopwatch.StartNew();Pump(()=>clock.ElapsedMilliseconds>310);}
static void Capture(ManagerForm form,string path){form.Update();using(var b=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(b))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);b.Save(path);}}
public static void Run(ManagerForm form,string dir){Directory.CreateDirectory(dir);form.SavePath=Path.Combine(dir,"test-career.json");form.SettingsPath=Path.Combine(dir,"test-settings.json");try{
form.State=null;form.SwitchView("menu");Settle();Capture(form,Path.Combine(dir,"menu.png"));Check(form.View=="menu"&&form.State==null,"fresh launch displays the main menu before team selection");form.Play();Settle();Capture(form,Path.Combine(dir,"teams.png"));Check(form.View=="teams"&&form.State==null,"Play opens team selection without creating a career");
foreach(string code in TyrePhotos.Codes)Check(TyrePhotos.Get(code)!=null,"embedded tyre product image: "+code);
for(int i=0;i<11;i++)Check(TeamLogos.Get(i)!=null,"embedded original team logo: "+i);
form.OpenSettings();Settle();Capture(form,Path.Combine(dir,"settings.png"));var bounds=form.Bounds;var state=form.WindowState;form.SetFullscreen(true);Application.DoEvents();Check(form.Preferences.Fullscreen&&form.FormBorderStyle==FormBorderStyle.None&&form.Bounds==Screen.FromControl(form).Bounds,"fullscreen fills the screen without window borders");Check(GameSettings.Load(form.SettingsPath).Fullscreen,"fullscreen preference persists to disk");form.SetFullscreen(false);Application.DoEvents();Check(form.Bounds==bounds&&form.WindowState==state&&form.FormBorderStyle==FormBorderStyle.Sizable,"leaving fullscreen restores window bounds and borders");form.Preferences.Animations=false;form.Preferences.Save(form.SettingsPath);Check(!GameSettings.Load(form.SettingsPath).Animations,"reduced motion preference persists");form.Preferences.Animations=true;
form.State=Data.Create(0,"",658291);string career=Engine.Serialize(form.State);form.SwitchView("menu");Settle();Capture(form,Path.Combine(dir,"menu-resume.png"));form.Play();Check(form.View=="game"&&Engine.Serialize(form.State)==career,"Play resumes an existing career without replacing it");Engine.Develop(form.State,"front",4);Engine.Develop(form.State,"floor",6);
string[] pages={"home","development","facilities","people","race","contracts","calendar","standings","archive","hall","save"};foreach(string page in pages)form.Capture(page,Path.Combine(dir,page+".png"));Check(true,"all eleven game pages render at 1440 px");foreach(var person in form.State.People.Where(p=>p.Kind==0&&p.Id<22))Check(DriverPhotos.Get(person)!=null,"portrait decodes: "+person.Name);
form.Size=new Size(1120,780);form.Capture("people",Path.Combine(dir,"small-people.png"));form.Capture("race",Path.Combine(dir,"small-race.png"));Check(true,"people and weekend render at 1120 px");form.Size=new Size(1440,960);
int openForms=Application.OpenForms.Count;var elapsed=Stopwatch.StartNew();form.SimulateNext();Check(form.ActiveOverlay is SimulationOverlay&&Application.OpenForms.Count==openForms,"simulation opens inside the game instead of creating a separate window");Settle();Capture(form,Path.Combine(dir,"simulation-0.png"));Settle();Capture(form,Path.Combine(dir,"simulation-1.png"));Pump(()=>form.ActiveOverlay==null);Check(elapsed.Elapsed.TotalSeconds>=1.1&&form.State.Stage==1,"instant simulation shows its animation and commits a complete practice");Check(!File.ReadAllBytes(Path.Combine(dir,"simulation-0.png")).SequenceEqual(File.ReadAllBytes(Path.Combine(dir,"simulation-1.png"))),"simulation frames animate");
while(form.State.Stage<6)Engine.SimulateSession(form.State);form.State.Weekend.Weather="Дождь";form.Capture("race",Path.Combine(dir,"before-race.png"));string before=Engine.Serialize(form.State);form.SimulateNext();var selector=form.ActiveOverlay as StrategyOverlay;Check(selector!=null&&Application.OpenForms.Count==openForms,"strategy selection is an in-game overlay with no extra application window");Settle();Capture(form,Path.Combine(dir,"strategy-rain.png"));Check(!Children(selector).OfType<ComboBox>().Any(),"strategy overlay uses visual cards instead of a native dropdown");Check(selector.PlanChoices.All(c=>c.Length==4)&&selector.Stops.Length==2&&selector.StintChoices.All(c=>c.Count>0),"each driver has independent strategy inputs");selector.StintChoices[0][0].PerformClick();Application.DoEvents();Capture(form,Path.Combine(dir,"tyre-picker.png"));ChooseTyre(selector,0,0,"I");selector.CancelButton.PerformClick();Pump(()=>form.ActiveOverlay==null);Check(before==Engine.Serialize(form.State),"cancelling strategy selection preserves the career");
form.SimulateNext();selector=(StrategyOverlay)form.ActiveOverlay;Settle();selector.Stops[0].Text="not a lap";selector.ConfirmButton.PerformClick();Check(form.ActiveOverlay==selector&&selector.ErrorLabel.Text.Length>0&&before==Engine.Serialize(form.State),"invalid strategy input produces an inline error and no partial changes");selector.Stops[0].Text="20";ChooseTyre(selector,0,0,"I");ChooseTyre(selector,0,1,"I");selector.PlanChoices[1][1].PerformClick();selector.Stops[1].Text="15,35";ChooseTyre(selector,1,0,"I");ChooseTyre(selector,1,1,"W");ChooseTyre(selector,1,2,"I");Capture(form,Path.Combine(dir,"strategy-inline-error.png"));selector.ConfirmButton.PerformClick();Pump(()=>form.ActiveOverlay==null);Check(form.State.Round==1&&form.State.Archive.Count==1,"rain strategy I,I confirms and completes a race without MissingMethodException");form.Capture("race",Path.Combine(dir,"race-results.png"));Check(Engine.Deserialize(File.ReadAllText(form.SavePath)).Archive.Count==1,"race result is saved to disk");
// Dry strategies also retain different pit schedules for the two drivers.
form.State=Data.Create(0,"",935);form.State.Stage=6;Engine.PrepareWeekend(form.State);form.State.Weekend.Weather="Сухо";form.SimulateNext();selector=(StrategyOverlay)form.ActiveOverlay;Settle();selector.PlanChoices[0][0].PerformClick();selector.PlanChoices[1][1].PerformClick();selector.Stops[0].Text="20";selector.Stops[1].Text="15,35";ChooseTyre(selector,1,0,"S");ChooseTyre(selector,1,1,"M");ChooseTyre(selector,1,2,"H");form.Size=new Size(1120,780);Settle();Capture(form,Path.Combine(dir,"strategy-small.png"));Check(selector.ConfirmButton.Bottom<=selector.ConfirmButton.Parent.ClientSize.Height,"strategy confirmation stays visible at minimum window size");selector.ConfirmButton.PerformClick();Pump(()=>form.ActiveOverlay==null);Check(form.State.Archive.Count==1,"dry strategies confirm and complete a race");form.Size=new Size(1440,960);
form.State.Stage=4;Engine.PrepareWeekend(form.State);form.SimulateNext();selector=(StrategyOverlay)form.ActiveOverlay;Settle();Capture(form,Path.Combine(dir,"strategy-sprint.png"));selector.AddStop[0].PerformClick();Check(selector.StintChoices[0].Count==2,"sprint allows adding an optional pit stop with a visual stint");ChooseTyre(selector,0,1,"H");selector.ConfirmButton.PerformClick();Pump(()=>form.ActiveOverlay==null);Check(form.State.Stage==5&&form.State.Weekend.Results.Last().Name=="Спринт","sprint selection and simulation work inside the same window");
form.State=Data.Create(0,"",936);form.State.Round=22;form.State.Stage=6;Engine.PrepareWeekend(form.State);form.SimulateNext();selector=(StrategyOverlay)form.ActiveOverlay;Settle();selector.ConfirmButton.PerformClick();Pump(()=>form.ActiveOverlay==null);Check(form.State.SeasonDone&&form.State.Round==23,"in-game animation safely completes the season finale");form.Capture("race",Path.Combine(dir,"season-finale.png"));
report.Add("\n"+report.Count+" UI checks passed under Mono/Xvfb. Native Windows execution requires a Windows host.");
}catch(Exception ex){Environment.ExitCode=1;report.Add("FAIL "+ex);}finally{File.WriteAllLines(Path.Combine(dir,"ui-test.txt"),report);form.Close();}}
}
}
